export const DECK_FAIR_ADDITIONS = EDITS.map(row => row.name);

/** The same edits as patch rows ({ id, addition, file, from, to }), in the order they must be applied. */
export function deckFairPatches() {
  return EDITS.map(row => ({ id: `deck-fair-${row.name}`, addition: row.name, file: DECK_FAIR_FILE, from: row.from, to: row.to }));
}

/**
 * One bundled file with Round 1327 taken out. `relative` is the file's path from the repo root; any other file
 * comes back as it was. `receipt` gains one row per edit made, for the harness's proof.
 */
export function inverseDeckFair(relative, source, receipt = []) {
  if (relative !== DECK_FAIR_FILE) return source;
  let out = source.split('\r\n').join('\n');
  for (const row of EDITS) {
    assert.equal(out.split(row.from).length, 2, `the ${row.name} row of Round 1327's inverse must be in ${DECK_FAIR_FILE} exactly once at its turn`);
    out = out.replace(row.from, () => row.to);
    receipt.push({ addition: row.name, file: DECK_FAIR_FILE });
  }
  return out;
}

/** The same as an esbuild plugin, for a bundle of the tree at `root` that loads the real engine. */
export function deckFairOutPlugin(root, pathMod, fsMod, receipt = []) {
  const target = pathMod.resolve(root, DECK_FAIR_FILE).split(pathMod.sep).join('/').toLowerCase();
  return { name: 'deck-fair-out', setup(b) {
    b.onLoad({ filter: /soccerCareerEngine\.ts$/ }, args => {
      if (pathMod.resolve(args.path).split(pathMod.sep).join('/').toLowerCase() !== target) return undefined;
      return { contents: inverseDeckFair(DECK_FAIR_FILE, fsMod.readFileSync(args.path, 'utf8'), receipt), loader: 'ts' };
    });
  } };
}
